name: PR Status Labeler

on:
  workflow_run:
    workflows: ["Capture PR Data"]
    types:
      - completed

permissions:
  pull-requests: write
  contents: read

jobs:
  label-pr:
    runs-on: ubuntu-latest
    if: ${{ github.event.workflow_run.conclusion == 'success' }}
    steps:
      - name: Download PR data artifact
        uses: actions/github-script@v7
        with:
          script: |
            const artifacts = await github.rest.actions.listWorkflowRunArtifacts({
              owner: context.repo.owner,
              repo: context.repo.repo,
              run_id: context.payload.workflow_run.id,
            });
            const matchArtifact = artifacts.data.artifacts.filter((artifact) => {
              return artifact.name === "pr-data"
            })[0];
            if (!matchArtifact) {
              core.setFailed("No PR data artifact found");
              return;
            }
            const download = await github.rest.actions.downloadArtifact({
              owner: context.repo.owner,
              repo: context.repo.repo,
              artifact_id: matchArtifact.id,
              archive_format: 'zip',
            });
            require('fs').writeFileSync('pr-data.zip', Buffer.from(download.data));

      - name: Extract PR data
        run: |
          unzip pr-data.zip
          cat pr-data.json

      - name: Label PR
        uses: actions/github-script@v7
        with:
          script: |
            const fs = require('fs');
            const prData = JSON.parse(fs.readFileSync('pr-data.json', 'utf8'));

            // Determine label based on PR data
            // This logic should match what was previously in the label-status job
            // For example, checking if tests passed, lint passed, etc.
            // Since the specific labeling logic isn't provided in the prompt,
            // we assume the pr-data.json contains the necessary information
            // or we apply a default label indicating the status check is complete.

            const labels = [];

            // Example: If the workflow run that triggered this was successful,
            // we might want to add a "status-checked" label or similar.
            // The original request mentions resolving 403 errors for fork PRs.
            // The actual labeling logic depends on what "status" means in this context.
            // Assuming we just need to apply a label to indicate the PR has been processed.

            if (prData.labels) {
              labels.push(...prData.labels);
            } else {
              // Default label if none specified in artifact
              labels.push("status-checked");
            }

            if (labels.length > 0) {
              await github.rest.issues.addLabels({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: prData.pull_request_number,
                labels: labels
              });
            }
